"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { songCoverPath } from "@/lib/songCover";
import { CalendarDays, Camera, CheckCircle2, ChevronDown, Clapperboard, Ellipsis, Film, GripVertical, Images, LayoutGrid, List, ListTodo, MapPin, PanelsTopLeft, Palette, Pencil, Plus, Rocket, Trash2, Users, Video } from "lucide-react";

type Project = { id: string; visibility: string; status: string; public_concept: string; public_status: string; next_action: string; workspace: Record<string, any>; assigned_videographer?: Record<string, any>; songs?: { title: string; slug: string } };
type Stage = "creative" | "production" | "release";
type Row = Record<string, any>;
const stages: Array<[Stage, string, typeof Palette]> = [["creative", "Creative", Palette], ["production", "Production", Video], ["release", "Release", Rocket]];
const makeId = () => typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const panel = "rounded-2xl border border-white/[.08] bg-[#111116]";
const field = "w-full rounded-lg border border-white/10 bg-black/25 px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/30 focus:border-[#FD52AF]/60";

function cleanConcept(value: Row, index: number): Row {
  const scenes = Array.isArray(value.scenes) ? value.scenes.map((scene: Row, i: number) => ({ ...scene, id: scene.id || makeId(), number: i + 1, description: scene.description || scene.synopsis || "", referenceUrl: scene.referenceUrl || scene.reference_url || "", status: scene.status || "planned", characters: Array.isArray(scene.characters) ? scene.characters : [], shots: Array.isArray(scene.shots) ? scene.shots : [] })) : [];
  return { ...value, id: value.id || makeId(), title: value.title || `Concept ${index + 1}`, synopsis: value.synopsis || value.story || "", styles: Array.isArray(value.styles) ? value.styles : [], scenes };
}
function initials(name: string) { return name.trim().split(/\s+/).slice(0, 2).map(word => word[0]).join("").toUpperCase() || "＋"; }

export default function MusicVideoWorkspace({ id, embedded = false }: { id: string; embedded?: boolean }) {
  const [project, setProject] = useState<Project | null>(null);
  const [stage, setStage] = useState<Stage>("creative");
  const [notice, setNotice] = useState("Loading project…");
  const [activeScene, setActiveScene] = useState<string | null>(null);
  const [itemModal, setItemModal] = useState<{ type: string; index: number | null; value: Row } | null>(null);
  const [versionsOpen, setVersionsOpen] = useState(false);
  const [menuScene, setMenuScene] = useState<string | null>(null);
  const [sceneView, setSceneView] = useState<"grid" | "list">("grid");
  const [readinessOpen, setReadinessOpen] = useState(false);
  const [invites, setInvites] = useState<Record<string, { id: string; email: string; link?: string }>>({});
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const dragScene = useRef<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const response = await fetch(`/api/music-video-projects?id=${id}`, { cache: "no-store" });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || "Unable to load project.");
        const data = result.project as Project;
        const workspace = data.workspace || {};
        const oldConcepts = Array.isArray(workspace.creative?.concepts) ? workspace.creative.concepts : [];
        const title = String(data.songs?.title || "").toUpperCase();
        if (!oldConcepts.length && title.includes("AM I PRETTY WHEN I CRY")) {
          const legacy = await import("@/lib/musicVideoStarterConcepts").catch(() => null);
          if (legacy?.defaultConcepts) {
            workspace.creative = { ...(workspace.creative || {}), concepts: legacy.defaultConcepts(), selectedConceptId: "butterfly-switch" };
            await fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: data.id, workspace }) });
          }
        }
        const inviteResponse = await fetch(`/api/music-video-invites?projectId=${encodeURIComponent(id)}`, { cache: "no-store" }).catch(() => null);
        if (inviteResponse?.ok) {
          const inviteData = await inviteResponse.json();
          if (!cancelled) setInvites(Object.fromEntries((inviteData.invites || []).map((invite: { id: string; email: string; expiresAt: string }) => [invite.email.toLowerCase(), { id: invite.id, email: invite.email }])));
        }
        if (!cancelled) { setProject({ ...data, workspace }); setNotice(""); }
      } catch (error) { if (!cancelled) setNotice(error instanceof Error ? error.message : "Unable to load project."); }
    })();
    return () => { cancelled = true; if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [id]);

  const workspace = project?.workspace || {};
  const creative = workspace.creative || {};
  const production = workspace.production || {};
  const release = workspace.release || {};
  const concepts: Row[] = useMemo(() => {
    const rows = Array.isArray(creative.concepts) ? creative.concepts : [];
    if (rows.length) return rows.map(cleanConcept);
    const legacyStory = creative.story || creative.overallConcept || "";
    const legacyScenes = Array.isArray(creative.scenes) ? creative.scenes : [];
    if (legacyStory || creative.aesthetic || creative.directorNotes || creative.visualReferences || legacyScenes.length) return [cleanConcept({ id: "legacy-main", title: creative.title || "Main concept", synopsis: legacyStory, styles: creative.styles || [], theme: creative.theme || creative.themes || "", aesthetic: creative.aesthetic || "", scenes: legacyScenes, decision: creative.decision || "", notes: creative.directorNotes || "", references: creative.visualReferences || "", shotList: creative.shotList || [] }, 0)];
    return [];
  }, [creative]);
  const selectedId = creative.selectedConceptId || concepts.find(row => !row.archived)?.id || concepts[0]?.id;
  const concept = concepts.find(row => row.id === selectedId) || concepts[0] || cleanConcept({ id: "new-concept", title: "New video concept", synopsis: "", styles: [], scenes: [] }, 0);
  const scenes: Row[] = concept.scenes || [];
  const people = workspace.people || {};
  const castStored: Row[] = Array.isArray(people.actors) ? people.actors : [];
  const cast: Row[] = [...castStored];
  if (project?.assigned_videographer?.name && !cast.some(person => person.email === project.assigned_videographer?.email || person.name === project.assigned_videographer?.name)) cast.push({ ...project.assigned_videographer, id: "assigned-videographer", role: "Videographer", status: "Invited" });
  const locations: Row[] = Array.isArray(people.locations) ? people.locations : [];
  const outfits: Row[] = Array.isArray(people.outfits) ? people.outfits : [];
  const props: Row[] = Array.isArray(people.props) ? people.props : [];
  const tasks: Row[] = Array.isArray(production.tasks) ? production.tasks : [];
  const active = scenes.find(scene => scene.id === activeScene) || null;
  const releasePublished = release.publicationConfirmed === true || release.publicationStatus === "Published";
  const editingStatus = ["Approved", "Complete"].includes(release.editingStatus) ? "Final" : ["In Review", "Ready for review"].includes(release.editingStatus) ? "In Review" : ["Editing", "In progress"].includes(release.editingStatus) ? "Editing" : "Not Started";
  const overall = releasePublished ? "Published" : editingStatus === "Final" && release.finalApproved === "yes" ? "Ready to publish" : scenes.length && scenes.every(scene => scene.status === "filmed") ? "Filming complete" : scenes.length ? "In production" : "Concept";
  const nextStep = !concept.synopsis?.trim() ? "Write a one-line video idea" : !scenes.length ? "Add your first storyboard scene" : !production.shootDate ? "Choose a shoot date" : !tasks.some(task => task.status !== "Done") ? "Review the edit and approve the final video" : (tasks.find(task => task.status !== "Done")?.name || "Check the next shoot task");
  const doneTasks = tasks.filter(task => task.status === "Done").length;
  const stageProgress = {
    creative: Boolean(concept.synopsis?.trim()) || scenes.length > 0,
    production: Boolean(production.shootDate) || doneTasks > 0 || scenes.some(scene => scene.status === "filmed"),
    release: releasePublished,
  };
  const readinessMissing = [!production.shootDate && "Shoot date", locations.length > 0 && !locations.some((row: Row) => ["Confirmed", "Secured", "Completed"].includes(row.status)) && "Confirmed location", cast.length > 0 && !cast.some((row: Row) => ["Confirmed", "Completed"].includes(row.status)) && "Confirmed cast"].filter(Boolean) as string[];
  const savedLocationNames = locations.map((row: Row) => row.name).filter(Boolean);
  const savedCastNames = cast.map((row: Row) => row.name).filter(Boolean);
  const savedOutfitNames = [...outfits, ...props].map((row: Row) => row.name).filter(Boolean);

  function queueSave(nextWorkspace: Row) {
    if (!project) return;
    setProject(current => current ? { ...current, workspace: nextWorkspace } : current);
    setNotice("Saving…");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        const nextRelease = nextWorkspace.release || {};
        const nextScenes = (nextWorkspace.creative?.concepts || []).find((row: Row) => row.id === nextWorkspace.creative?.selectedConceptId)?.scenes || [];
        const status = nextRelease.publicationConfirmed === true || nextRelease.publicationStatus === "Published" ? "complete" : nextRelease.editingStatus && nextRelease.editingStatus !== "Not Started" ? "editing" : nextScenes.length && nextScenes.every((scene: Row) => scene.status === "filmed") ? "filming" : nextScenes.length ? "planning" : "concept";
        const response = await fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: project.id, workspace: nextWorkspace, status }) });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || "Save failed.");
        setNotice("Saved");
      } catch (error) { setNotice(error instanceof Error ? error.message : "Save failed."); }
    }, 450);
  }
  function update(section: string, value: Row) { queueSave({ ...workspace, [section]: value }); }
  function updateCreative(value: Row) { update("creative", value); }
  function updateConcept(patch: Row) { const next = concepts.length ? concepts.map(row => row.id === concept.id ? { ...row, ...patch } : row) : [{ ...concept, ...patch }]; updateCreative({ ...creative, concepts: next, selectedConceptId: concept.id }); }
  function updateScenes(value: Row[]) { updateConcept({ scenes: value.map((scene, index) => ({ ...scene, number: index + 1 })) }); }
  function updateScene(sceneId: string, patch: Row) { updateScenes(scenes.map(scene => scene.id === sceneId ? { ...scene, ...patch } : scene)); }
  function updatePeople(key: string, rows: Row[]) { update("people", { ...people, [key]: rows }); }
  function updateProduction(patch: Row) { update("production", { ...production, ...patch }); }
  function updateRelease(patch: Row) { const next = { ...release, ...patch }; if (patch.publicationConfirmed === true) { next.publicationStatus = "Published"; next.publicationDate = next.publicationDate || new Date().toISOString().slice(0, 10); } if (patch.publicationConfirmed === false && next.publicationStatus === "Published") next.publicationStatus = "Not published"; update("release", next); }
  async function inviteVideographer(person: Row) {
    const email = String(person.email || "").trim();
    if (!email) { setNotice("Add an email address to invite this person."); return; }
    const response = await fetch("/api/music-video-invites", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId: id, emails: [email] }) });
    const result = await response.json();
    if (!response.ok) { setNotice(result.error || "Unable to create invite."); return; }
    const invite = result.invites?.[0];
    if (invite) { setInvites(current => ({ ...current, [email.toLowerCase()]: invite })); setNotice(result.emailStatus === "sent" ? "Invite sent" : "Private invite link ready"); }
  }
  async function revokeInvite(email: string) {
    const key = email.toLowerCase(), invite = invites[key]; if (!invite) return;
    const response = await fetch("/api/music-video-invites", { method: "DELETE", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: invite.id }) });
    if (response.ok) { setInvites(current => { const next = { ...current }; delete next[key]; return next; }); setNotice("Invite revoked"); }
  }
  async function uploadReference(file: File, onDone: (url: string) => void) {
    if (!file.type.startsWith("image/")) { setNotice("Choose an image file."); return; }
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        const scale = Math.min(1, 1000 / Math.max(image.width, image.height));
        const canvas = document.createElement("canvas"); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale);
        const context = canvas.getContext("2d"); if (!context) return;
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        const url = canvas.toDataURL("image/jpeg", 0.72);
        if (url.length > 180_000) { setNotice("That image is too large. Try a smaller image."); return; }
        onDone(url);
      };
      image.src = String(reader.result || "");
    };
    reader.readAsDataURL(file);
  }

  if (!project) return embedded ? <p className="p-4 text-sm text-white/55">{notice}</p> : <main className="min-h-screen bg-[#09090c] p-8 text-white">{notice}</main>;
  const Root = embedded ? "section" : "main";
  return <Root className={`${embedded ? "rounded-2xl border border-white/[.08] bg-[#0b0b0f] p-3 sm:p-5" : "min-h-screen bg-[#09090c] p-4 text-white sm:p-8"} text-white`}>
    {!embedded && <Link href={`/admin?view=songs&song=${encodeURIComponent(project.songs?.slug || "")}`} className="mb-4 inline-block text-xs text-white/45 hover:text-white">← Song workspace</Link>}
    <header className="flex flex-wrap items-center gap-3 border-b border-white/[.08] pb-4">
      {!embedded && <img src={songCoverPath(project.songs?.slug || "", project.songs?.title || "")} alt="" className="h-14 w-14 rounded-xl border border-white/10 object-cover" />}
      <div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><Clapperboard size={18} strokeWidth={1.8} className="text-white/45"/>{!embedded && <h1 className="truncate text-lg font-bold">{project.songs?.title || "Music Video"}</h1>}<span className="rounded-full bg-white/[.06] px-2.5 py-1 text-[.62rem] font-semibold text-white/65">{workspace.videoType || "Official Music Video"}</span><span className="rounded-full border border-[#FD52AF]/30 px-2.5 py-1 text-[.62rem] font-semibold text-[#FD52AF]">{overall}</span></div><p className="mt-1 truncate text-xs text-white/45">{scenes.length} scenes <span className="px-1">·</span> Tasks {doneTasks}/{tasks.length} <span className="px-1">·</span> Shoot {production.shootDate || "Not scheduled"} <span className="px-1">·</span> Next: {nextStep}</p></div>
      <span className="text-[.65rem] text-white/40" aria-live="polite">{notice}</span>
    </header>
    <nav aria-label="Music video stages" className="my-4 grid grid-cols-3 rounded-xl bg-white/[.035] p-1">{stages.map(([key, label, Icon]) => <button key={key} type="button" onClick={() => setStage(key)} className={`flex items-center justify-center gap-2 rounded-lg px-3 py-2.5 text-sm font-semibold transition ${stage === key ? "bg-[#FD52AF] text-black" : "text-white/50 hover:text-white"}`}><Icon size={17} strokeWidth={1.8}/>{label}{stageProgress[key] && <CheckCircle2 size={13} className={stage === key ? "text-black/70" : "text-emerald-300/75"}/>}</button>)}</nav>
    <div className={`${panel} mb-4 flex flex-wrap items-center gap-2 px-3 py-2.5`}><span className="mr-auto text-xs font-semibold"><span className={readinessMissing.length ? "text-amber-200" : "text-emerald-200"}>Shoot readiness: {readinessMissing.length ? "Needs attention" : "Ready"}</span>{readinessOpen && readinessMissing.length > 0 && <span className="ml-2 text-white/45">Missing {readinessMissing.join(" · ")}</span>}</span><button type="button" onClick={() => setReadinessOpen(!readinessOpen)} aria-expanded={readinessOpen} className="flex items-center gap-1 text-xs text-white/45 hover:text-white">{readinessOpen ? "Hide" : "Details"}<ChevronDown size={14} className={readinessOpen ? "rotate-180" : ""}/></button></div>

    {stage === "creative" && <div className="space-y-4">
      <section className={`${panel} p-4 sm:p-5`}>
        <div className="flex items-start gap-3"><div className="min-w-0 flex-1"><label className="flex items-center gap-2 text-[.65rem] font-bold uppercase tracking-[.15em] text-[#FD52AF]"><Palette size={16}/>The vision</label><input aria-label="Video concept title" value={concept.title || ""} onChange={event => updateConcept({ title: event.target.value })} className="mt-1 w-full bg-transparent text-xl font-bold outline-none placeholder:text-white/30" placeholder="Give your video a name"/><textarea aria-label="Video concept" value={concept.synopsis || ""} onChange={event => updateConcept({ synopsis: event.target.value, story: event.target.value })} rows={2} placeholder="Describe the video in a sentence or two…" className="mt-2 w-full resize-y bg-transparent text-sm leading-6 text-white/65 outline-none placeholder:text-white/30"/></div>
          <div className="relative"><button type="button" aria-label="Concept versions" onClick={() => setVersionsOpen(!versionsOpen)} className="rounded-lg px-3 py-2 text-xl text-white/55 hover:bg-white/[.06]">···</button>{versionsOpen && <div className="absolute right-0 top-10 z-30 w-56 rounded-xl border border-white/10 bg-[#17171c] p-1 shadow-xl">{concepts.map((row, index) => <button key={row.id} type="button" onClick={() => { updateCreative({ ...creative, concepts: concepts.map(item => item.id === row.id ? row : item), selectedConceptId: row.id }); setVersionsOpen(false); }} className={`block w-full truncate rounded-lg px-3 py-2 text-left text-xs ${row.id === concept.id ? "bg-[#FD52AF]/15 text-[#ff9dcd]" : "text-white/70 hover:bg-white/[.06]"}`}>{row.title || `Concept ${index + 1}`}{row.archived ? " · Archived" : ""}</button>)}<button type="button" onClick={() => { const row = cleanConcept({ id: makeId(), title: `Concept ${concepts.length + 1}`, synopsis: "", styles: [], scenes: [] }, concepts.length); updateCreative({ ...creative, concepts: [...concepts, row], selectedConceptId: row.id }); setVersionsOpen(false); }} className="mt-1 block w-full rounded-lg border-t border-white/10 px-3 py-2 text-left text-xs font-semibold text-[#FD52AF]">＋ New version</button></div>}</div>
        </div>
        <div className="mt-3 flex flex-wrap gap-1.5">{["Cinematic", "Dreamy", "Raw", "Playful", "Intimate", "Surreal", "Performance", ...(concept.customStyles || [])].map((style: string) => <button key={style} type="button" onClick={() => updateConcept({ styles: (concept.styles || []).includes(style) ? concept.styles.filter((item: string) => item !== style) : [...(concept.styles || []), style] })} className={`rounded-full border px-2.5 py-1 text-[.68rem] ${concept.styles?.includes(style) ? "border-[#FD52AF]/45 bg-[#FD52AF]/10 text-[#ff9dcd]" : "border-white/10 text-white/45"}`}>{style}</button>)}<button type="button" onClick={() => { const name = window.prompt("Add a visual style"); if (name?.trim()) updateConcept({ customStyles: [...(concept.customStyles || []), name.trim()], styles: [...(concept.styles || []), name.trim()] }); }} className="rounded-full border border-dashed border-white/15 px-2.5 py-1 text-[.68rem] text-white/40">＋</button></div>
        <div className="mt-4 flex flex-wrap items-center gap-2"><span className="mr-auto flex items-center gap-1.5 text-[.68rem] font-semibold text-white/45"><Images size={15}/>Inspiration</span>{(concept.inspirationImages || []).map((url: string, index: number) => <button key={`${index}-${url.slice(0, 16)}`} type="button" title="Remove image" aria-label="Remove inspiration image" onClick={() => updateConcept({ inspirationImages: concept.inspirationImages.filter((_: string, i: number) => i !== index) })} className="group relative h-14 w-14 overflow-hidden rounded-lg"><img src={url} alt="Inspiration" className="h-full w-full object-cover"/><span className="absolute inset-0 hidden place-items-center bg-black/60 text-white group-hover:grid"><Trash2 size={15}/></span></button>)}<label className="flex cursor-pointer items-center gap-1.5 rounded-lg border border-dashed border-white/15 px-3 py-2 text-[.68rem] text-white/50 hover:border-[#FD52AF]/40"><Plus size={14}/>Image<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => updateConcept({ inspirationImages: [...(concept.inspirationImages || []), url] })); }}/></label><input aria-label="Inspiration image URL" placeholder="Paste image URL" onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); const input = event.currentTarget; if (input.value.trim()) { updateConcept({ inspirationImages: [...(concept.inspirationImages || []), input.value.trim()] }); input.value = ""; } } }} className="w-36 rounded-lg border border-white/10 bg-black/20 px-2 py-2 text-[.65rem] outline-none focus:border-[#FD52AF]/50"/></div>
        {(concept.decision || concept.notes || concept.references || concept.beginning || concept.middle || concept.ending || concept.shotList || concept.theme || concept.aesthetic) && <details className="mt-3 border-t border-white/[.06] pt-2"><summary className="cursor-pointer text-[.65rem] text-white/40">Older concept notes</summary><p className="mt-2 whitespace-pre-wrap text-xs text-white/55">{[concept.decision, concept.notes, concept.references, concept.theme && `Theme: ${concept.theme}`, concept.aesthetic && `Aesthetic: ${concept.aesthetic}`, concept.beginning && `Beginning: ${concept.beginning}`, concept.middle && `Middle: ${concept.middle}`, concept.ending && `Ending: ${concept.ending}`].filter(Boolean).join("\n\n")}</p>{concept.shotList && <pre className="mt-2 max-h-40 overflow-auto whitespace-pre-wrap text-xs text-white/45">{JSON.stringify(concept.shotList, null, 2)}</pre>}</details>}
      </section>
      <section aria-label="Storyboard" className={`${panel} overflow-hidden`}>
        <div className="flex items-center gap-3 px-4 py-3 sm:px-5"><div className="mr-auto"><h2 className="flex items-center gap-2 text-sm font-bold"><PanelsTopLeft size={18} className="text-white/45"/>Storyboard <span className="font-normal text-white/40">{scenes.length} scenes</span></h2><p className="text-[.68rem] text-white/40">Drag scenes to reorder. Select a card to edit.</p></div><div className="flex rounded-lg border border-white/10 p-0.5"><button type="button" aria-label="Grid view" onClick={() => setSceneView("grid")} className={`rounded-md p-1.5 ${sceneView === "grid" ? "bg-white/10 text-[#FD52AF]" : "text-white/40"}`}><LayoutGrid size={15}/></button><button type="button" aria-label="List view" onClick={() => setSceneView("list")} className={`rounded-md p-1.5 ${sceneView === "list" ? "bg-white/10 text-[#FD52AF]" : "text-white/40"}`}><List size={15}/></button></div><button type="button" onClick={() => { const scene = { id: makeId(), title: "", description: "", location: "", characters: [], outfit: "", props: "", shots: [], status: "planned" }; updateScenes([...scenes, scene]); setActiveScene(scene.id); }} className="flex items-center gap-1.5 rounded-lg bg-[#FD52AF] px-3 py-2 text-xs font-bold text-black"><Plus size={15}/>Add Scene</button></div>
        {!scenes.length ? <div className="m-4 grid min-h-48 place-items-center rounded-xl border border-dashed border-white/15 bg-white/[.02] text-center"><span><PanelsTopLeft size={20} className="mx-auto text-white/35"/><b className="mt-3 block text-sm">No scenes yet</b><span className="mt-1 block text-xs text-white/40">Start building your story.</span><button type="button" onClick={() => { const scene = { id: makeId(), title: "", description: "", location: "", characters: [], shots: [], status: "planned" }; updateScenes([scene]); setActiveScene(scene.id); }} className="mt-3 rounded-lg bg-[#FD52AF] px-3 py-2 text-xs font-bold text-black">Add your first scene</button></span></div> : <div className={sceneView === "grid" ? "grid grid-cols-1 gap-3 p-3 pt-1 sm:grid-cols-2 xl:grid-cols-3" : "space-y-2 p-3 pt-1"}>{scenes.map((scene, index) => <article key={scene.id} draggable onDragStart={() => { dragScene.current = scene.id; }} onDragOver={event => event.preventDefault()} onDrop={() => { const from = scenes.findIndex(row => row.id === dragScene.current), to = index; if (from < 0 || from === to) return; const next = [...scenes]; const [moved] = next.splice(from, 1); next.splice(to, 0, moved); dragScene.current = null; updateScenes(next); }} className={`group relative overflow-hidden rounded-xl border border-white/[.08] bg-[#0b0b0f] transition hover:border-white/20 ${sceneView === "list" ? "flex items-center" : ""}`}>
          <button type="button" onClick={() => setActiveScene(scene.id)} className={`text-left ${sceneView === "list" ? "flex min-w-0 flex-1 items-center gap-3" : "block w-full"}`}><div className={`relative bg-gradient-to-br from-[#2b1325] via-[#15131a] to-[#101014] ${sceneView === "list" ? "h-16 w-24 shrink-0" : "aspect-[16/9]"}`}>{scene.referenceUrl ? <img src={scene.referenceUrl} alt="" className="h-full w-full object-cover"/> : <div className="grid h-full place-items-center text-white/25"><span className="text-center"><Images size={18} className="mx-auto"/><span className="mt-1 block text-[.6rem]">Reference image</span></span></div>}<span className="absolute left-2 top-2 rounded-md bg-black/65 px-2 py-1 text-[.6rem] font-bold">SCENE {String(index + 1).padStart(2, "0")}</span></div><div className="min-w-0 p-3"><h3 className="truncate text-sm font-bold">{scene.title || "Untitled scene"}</h3><p className="mt-1 line-clamp-1 text-xs text-white/45">{scene.description || "Add a one-line scene description"}</p><p className="mt-2 truncate text-[.65rem] text-white/35">{scene.location || "Location TBD"}{scene.characters?.length ? ` · ${scene.characters.join(", ")}` : ""}</p></div></button>
          <button type="button" aria-label={`Scene ${index + 1} actions`} onClick={() => setMenuScene(menuScene === scene.id ? null : scene.id)} className="absolute right-2 top-12 rounded-lg bg-black/65 px-2 py-1 text-lg leading-none text-white/70 opacity-0 transition group-hover:opacity-100 focus:opacity-100">···</button>{menuScene === scene.id && <div className="absolute right-2 top-20 z-10 w-36 rounded-lg border border-white/10 bg-[#17171c] p-1 shadow-xl"><button onClick={() => { const clone = { ...scene, id: makeId(), title: `${scene.title || "Scene"} copy`, shots: (scene.shots || []).map((shot: Row) => ({ ...shot, id: makeId() })) }; updateScenes([...scenes.slice(0, index + 1), clone, ...scenes.slice(index + 1)]); setMenuScene(null); }} className="block w-full rounded px-2 py-1.5 text-left text-xs hover:bg-white/[.06]">Duplicate</button><button onClick={() => { if (window.confirm("Delete this scene?")) updateScenes(scenes.filter(row => row.id !== scene.id)); setMenuScene(null); }} className="block w-full rounded px-2 py-1.5 text-left text-xs text-rose-300 hover:bg-white/[.06]">Delete</button></div>}</article>)}</div>}
      </section>
    </div>}

    {stage === "production" && <div className="space-y-4">
      <section className={`${panel} grid gap-4 p-4 sm:grid-cols-[1fr_1.2fr] sm:p-5`}><div><h2 className="flex items-center gap-2 text-sm font-bold"><CalendarDays size={18} className="text-white/45"/>Shoot overview</h2><div className="mt-3 grid gap-2 sm:grid-cols-2"><label className="text-[.68rem] text-white/45">Shoot date<input type="date" value={production.shootDate || ""} onChange={event => updateProduction({ shootDate: event.target.value })} className={`${field} mt-1`}/></label><label className="text-[.68rem] text-white/45">Budget <span className="text-white/25">· optional</span><input type="text" value={production.budget || ""} onChange={event => updateProduction({ budget: event.target.value })} placeholder="$" className={`${field} mt-1`}/></label></div><textarea value={production.notes || ""} onChange={event => updateProduction({ notes: event.target.value })} rows={2} placeholder="Shoot notes (optional)" className={`${field} mt-2 resize-y`}/></div><div><div className="flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><ListTodo size={17} className="text-white/45"/>To-do list</h2><span className="text-xs text-white/40">{tasks.filter(task => task.status === "Done").length}/{tasks.length} done</span><button type="button" onClick={() => setItemModal({ type: "task", index: null, value: { name: "", status: "To Do", dueDate: "" } })} className="ml-3 rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-[#ff9dcd]">＋ Task</button></div><div className="mt-2 divide-y divide-white/[.06]">{tasks.map((task, index) => <div key={task.id || index} className="flex items-center gap-2 py-2"><input type="checkbox" checked={task.status === "Done"} onChange={event => updateProduction({ tasks: tasks.map((row, i) => i === index ? { ...row, status: event.target.checked ? "Done" : "To Do" } : row) })} className="accent-[#FD52AF]"/><button type="button" onClick={() => setItemModal({ type: "task", index, value: task })} className="min-w-0 flex-1 truncate text-left text-xs">{task.name || "Untitled task"}</button>{task.dueDate && <span className="text-[.62rem] text-white/35">{task.dueDate}</span>}<button type="button" aria-label="Task options" onClick={() => { if (window.confirm("Delete this task?")) updateProduction({ tasks: tasks.filter((_, i) => i !== index) }); }} className="px-1 text-white/35">×</button></div>)}{!tasks.length && <p className="py-4 text-xs text-white/35">No tasks yet. Add only what this video needs.</p>}</div></div></section>
      <section className={`${panel} p-4 sm:p-5`}><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><Users size={18} className="text-white/45"/>Cast &amp; crew</h2><button type="button" onClick={() => setItemModal({ type: "actors", index: null, value: { name: "", role: "", status: "Planned", email: "", phone: "", agreement: "" } })} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-[#ff9dcd]">＋ Person</button></div><CompactList rows={cast} empty="Add only the people this video needs." onAdd={() => setItemModal({ type: "actors", index: null, value: { name: "", role: "", status: "Planned" } })} onEdit={index => setItemModal({ type: "actors", index, value: cast[index] })} onRemove={index => { const person = cast[index]; if (person?.id === "assigned-videographer") { void fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, assigned_videographer: {} }) }); setProject(current => current ? { ...current, assigned_videographer: {} } : current); } else updatePeople("actors", castStored.filter(row => row.id !== person?.id)); }} onInvite={person => inviteVideographer(person)} inviteFor={person => invites[String(person.email || "").toLowerCase()]} onRevoke={person => revokeInvite(String(person.email || ""))} label="People"/></section>
      <div className="grid gap-4 lg:grid-cols-2"><section className={`${panel} p-4 sm:p-5`}><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><MapPin size={18} className="text-white/45"/>Locations</h2><button type="button" onClick={() => setItemModal({ type: "locations", index: null, value: { name: "", address: "", notes: "", status: "Idea" } })} className="text-xs text-[#ff9dcd]">＋ Add</button></div><CompactList rows={locations} empty="No location needed yet." onAdd={() => setItemModal({ type: "locations", index: null, value: { name: "", status: "Idea" } })} onEdit={index => setItemModal({ type: "locations", index, value: locations[index] })} onRemove={index => updatePeople("locations", locations.filter((_, i) => i !== index))} label="Locations"/></section>
      <section className={`${panel} p-4 sm:p-5`}><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><Camera size={18} className="text-white/45"/>Wardrobe &amp; props</h2><div className="flex gap-2"><button type="button" onClick={() => setItemModal({ type: "outfits", index: null, value: { name: "", status: "Needed", kind: "Outfit" } })} className="text-xs text-[#ff9dcd]">＋ Outfit</button><button type="button" onClick={() => setItemModal({ type: "props", index: null, value: { name: "", status: "Needed", kind: "Prop" } })} className="text-xs text-[#ff9dcd]">＋ Prop</button></div></div><div className="divide-y divide-white/[.06]">{[...outfits.map((row, index) => ({ ...row, _type: "outfits", _index: index })), ...props.map((row, index) => ({ ...row, _type: "props", _index: index }))].map(row => <button key={`${row._type}-${row.id || row._index}`} type="button" onClick={() => setItemModal({ type: row._type, index: row._index, value: row })} className="flex w-full items-center gap-3 py-2 text-left"><Thumb src={row.imageUrl || row.reference} name={row.name}/><span className="min-w-0 flex-1"><b className="block truncate text-xs">{row.name || "Untitled item"}</b><span className="text-[.62rem] text-white/40">{row.kind || (row._type === "props" ? "Prop" : "Outfit")}</span></span><span className="text-[.62rem] text-emerald-200/75">{row.status || "Needed"}</span></button>)}{!outfits.length && !props.length && <p className="py-4 text-xs text-white/35">Add wardrobe or props only when this shoot needs them.</p>}</div></section></div>
    </div>}

    {stage === "release" && <section className={`${panel} max-w-3xl p-4 sm:p-6`}><div className="flex flex-wrap items-center gap-3"><div className="mr-auto"><h2 className="flex items-center gap-2 text-base font-bold"><Film size={19} className="text-white/45"/>Finish &amp; publish</h2><p className="mt-1 text-xs text-white/45">Video release is separate from the song’s audio release.</p></div><span className={`rounded-full px-3 py-1 text-xs font-semibold ${releasePublished ? "bg-emerald-300/10 text-emerald-200" : "bg-white/[.06] text-white/50"}`}>{releasePublished ? "Published" : "Not published"}</span></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-xs text-white/50">Editing status<select value={editingStatus} onChange={event => updateRelease({ editingStatus: event.target.value })} className={`${field} mt-1`}><option>Not Started</option><option>Editing</option><option>In Review</option><option>Final</option></select></label><label className="text-xs text-white/50">Target video release date<input type="date" value={release.releaseDate || ""} onChange={event => updateRelease({ releaseDate: event.target.value })} className={`${field} mt-1`}/></label><label className="text-xs text-white/50 sm:col-span-2">Published video URL<input type="url" value={release.videoUrl || ""} onChange={event => updateRelease({ videoUrl: event.target.value })} placeholder="https://…" className={`${field} mt-1`}/></label></div><div className="mt-5 flex flex-wrap items-center gap-3 border-t border-white/[.07] pt-4"><span className="mr-auto text-sm">Final video approved</span><button type="button" aria-pressed={release.finalApproved === "yes"} onClick={() => updateRelease({ finalApproved: release.finalApproved === "yes" ? "no" : "yes" })} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${release.finalApproved === "yes" ? "bg-emerald-300/15 text-emerald-200" : "bg-white/[.06] text-white/55"}`}>{release.finalApproved === "yes" ? "Yes" : "No"}</button></div><label className="mt-4 flex cursor-pointer items-center gap-3 rounded-xl bg-white/[.035] p-3"><input type="checkbox" checked={releasePublished} onChange={event => updateRelease({ publicationConfirmed: event.target.checked, publicationStatus: event.target.checked ? "Published" : "Not published" })} className="h-4 w-4 accent-[#FD52AF]"/><span><b className="block text-sm">Confirm this video is published</b><span className="text-xs text-white/40">Saving a URL alone never changes publication status.</span></span></label></section>}

    {active && <div className="fixed inset-0 z-[150] flex items-end justify-center bg-black/75 p-0 backdrop-blur-sm sm:items-center sm:p-4" onMouseDown={event => { if (event.target === event.currentTarget) setActiveScene(null); }}><section role="dialog" aria-modal="true" aria-label={`Scene details: ${active.title}`} className="h-[100dvh] w-full overflow-y-auto border border-white/10 bg-[#111116] p-4 shadow-2xl sm:h-auto sm:max-h-[92vh] sm:max-w-5xl sm:rounded-2xl sm:p-6"><div className="flex items-center gap-3"><div className="mr-auto"><p className="text-[.62rem] font-bold uppercase tracking-[.14em] text-[#FD52AF]">Scene {scenes.findIndex(row => row.id === active.id) + 1}</p><h2 className="mt-1 text-lg font-bold">Scene details</h2></div><button type="button" onClick={() => setActiveScene(null)} aria-label="Close scene" className="rounded-lg px-3 py-2 text-white/55 hover:bg-white/[.06]">✕</button></div><div className="mt-4 grid gap-4 sm:grid-cols-[1fr_1.1fr]"><div><div className="relative aspect-[4/3] overflow-hidden rounded-xl bg-gradient-to-br from-[#2b1325] to-[#101014]">{active.referenceUrl ? <img src={active.referenceUrl} alt="Scene inspiration" className="h-full w-full object-cover"/> : <div className="grid h-full place-items-center text-xs text-white/35">Scene reference image</div>}<label className="absolute bottom-2 right-2 cursor-pointer rounded-lg bg-black/75 px-3 py-2 text-xs">Upload image<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => updateScene(active.id, { referenceUrl: url })); }}/></label></div><input value={active.referenceUrl?.startsWith("data:") ? "" : active.referenceUrl || ""} onChange={event => updateScene(active.id, { referenceUrl: event.target.value })} placeholder="Or paste an image URL" className={`${field} mt-2 text-xs`}/></div><div className="space-y-2"><input value={active.title || ""} onChange={event => updateScene(active.id, { title: event.target.value })} placeholder="Scene title" className={`${field} text-base font-semibold`}/><textarea value={active.description || ""} onChange={event => updateScene(active.id, { description: event.target.value })} rows={3} placeholder="What happens in this scene?" className={`${field} resize-y`}/><label className="block text-[.65rem] text-white/45">Location<select value={active.location || ""} onChange={event => updateScene(active.id, { location: event.target.value })} className={`${field} mt-1`}><option value="">Choose or add below…</option>{savedLocationNames.map(name => <option key={name}>{name}</option>)}</select><input value={active.location || ""} onChange={event => updateScene(active.id, { location: event.target.value })} onBlur={event => { const name = event.currentTarget.value.trim(); if (name && !locations.some((location: Row) => String(location.name).toLowerCase() === name.toLowerCase())) updatePeople("locations", [...locations, { id: makeId(), name, status: "Idea" }]); }} placeholder="Type a location to save it for this video" className={`${field} mt-1`}/></label><Selector label="Cast" options={savedCastNames} values={active.characters || []} onChange={values => updateScene(active.id, { characters: values })} onCreate={name => { if (!castStored.some(person => String(person.name).toLowerCase() === name.toLowerCase())) updatePeople("actors", [...castStored, { id: makeId(), name, role: "Actor", status: "Considering" }]); }}/><Selector label="Wardrobe & props" options={savedOutfitNames} values={[active.outfit, ...(Array.isArray(active.props) ? active.props : active.props ? [active.props] : [])].filter(Boolean)} onChange={values => updateScene(active.id, { outfit: values[0] || "", props: values.slice(1) })} onCreate={name => { if (![...outfits, ...props].some(item => String(item.name).toLowerCase() === name.toLowerCase())) updatePeople("props", [...props, { id: makeId(), name, kind: "Prop", status: "Needed" }]); }}/><label className="block text-[.65rem] text-white/45">Scene status<select value={active.status || "planned"} onChange={event => updateScene(active.id, { status: event.target.value })} className={`${field} mt-1`}><option value="planned">Planned</option><option value="ready">Ready</option><option value="filmed">Filmed</option></select></label></div></div><div className="mt-4 border-t border-white/[.07] pt-3"><div className="flex items-center"><h3 className="mr-auto text-xs font-bold">Optional shots</h3><button type="button" onClick={() => updateScene(active.id, { shots: [...(active.shots || []), { id: makeId(), text: "", done: false }] })} className="text-xs text-[#ff9dcd]">＋ Shot</button></div>{(active.shots || []).map((shot: Row, index: number) => <div key={shot.id || index} className="mt-2 flex items-center gap-2"><input type="checkbox" checked={!!shot.done} onChange={event => updateScene(active.id, { shots: active.shots.map((row: Row, i: number) => i === index ? { ...row, done: event.target.checked } : row) })} className="accent-[#FD52AF]"/><input value={shot.text || ""} onChange={event => updateScene(active.id, { shots: active.shots.map((row: Row, i: number) => i === index ? { ...row, text: event.target.value } : row) })} placeholder="Shot description" className={`${field} flex-1 text-xs`}/><button type="button" onClick={() => updateScene(active.id, { shots: active.shots.filter((_: Row, i: number) => i !== index) })} className="px-1 text-white/35">×</button></div>)}</div></section></div>}

    {itemModal && <ItemEditor modal={itemModal} onClose={() => setItemModal(null)} onUpload={file => uploadReference(file, url => setItemModal(current => current ? { ...current, value: { ...current.value, imageUrl: url } } : current))} onSave={value => { if (itemModal.type === "task") { const rows = [...tasks]; if (itemModal.index === null) rows.push({ ...value, id: value.id || makeId() }); else rows[itemModal.index] = { ...rows[itemModal.index], ...value }; updateProduction({ tasks: rows }); } else { const rows: Row[] = [...(people[itemModal.type] || [])]; if (itemModal.index === null) rows.push({ ...value, id: value.id || makeId() }); else if (itemModal.value.id === "assigned-videographer") rows.push({ ...value, id: makeId() }); else if (itemModal.index < rows.length) rows[itemModal.index] = { ...rows[itemModal.index], ...value }; else rows.push({ ...value, id: makeId() }); updatePeople(itemModal.type, rows); if (itemModal.type === "actors" && String(value.role || "").toLowerCase().includes("videographer")) void fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, assigned_videographer: { name: value.name, email: value.email, portfolio: value.portfolio } }) }).then(() => setProject(current => current ? { ...current, assigned_videographer: { name: value.name, email: value.email, portfolio: value.portfolio } } : current)); } setItemModal(null); }}/>
    }
  </Root>;
}

function Thumb({ src, name }: { src?: string; name?: string }) { return src ? <img src={src} alt="" className="h-9 w-9 rounded-lg object-cover"/> : <div className="grid h-9 w-9 place-items-center rounded-lg bg-white/[.06] text-[.6rem] text-white/45">{initials(name || "")}</div>; }
function CompactList({ rows, empty, onAdd, onEdit, onRemove, onInvite, inviteFor, onRevoke, label }: { rows: Row[]; empty: string; onAdd: () => void; onEdit: (index: number) => void; onRemove: (index: number) => void; onInvite?: (row: Row) => void; inviteFor?: (row: Row) => { id: string; email?: string; link?: string } | undefined; onRevoke?: (row: Row) => void; label: string }) { return <div className="divide-y divide-white/[.06]">{rows.map((row, index) => <div key={row.id || index} className="flex flex-wrap items-center gap-3 py-2"><Thumb src={row.imageUrl || row.reference} name={row.name}/><button type="button" onClick={() => onEdit(index)} className="min-w-0 flex-1 text-left"><b className="block truncate text-xs">{row.name || `Untitled ${label.toLowerCase().slice(0, -1)}`}</b><span className="block truncate text-[.62rem] text-white/40">{row.role || row.address || row.email || row.notes || row.kind || "Details"}</span></button><span className="text-[.62rem] text-white/40">{row.status || "Planned"}</span>{onInvite && String(row.role || "").toLowerCase().includes("videographer") && <>{inviteFor?.(row) ? <><span className="max-w-28 truncate text-[.62rem] text-[#ff9dcd]">{inviteFor(row)?.link ? <a href={inviteFor(row)?.link} className="underline">Private invite</a> : "Invite active"}</span><button type="button" onClick={() => onRevoke?.(row)} className="text-[.62rem] text-rose-300">Revoke</button></> : <button type="button" onClick={() => onInvite(row)} className="rounded-md border border-[#FD52AF]/25 px-2 py-1 text-[.62rem] text-[#ff9dcd]">Invite</button>}</>}<button type="button" onClick={() => onRemove(index)} aria-label={`Remove ${row.name || label}`} className="text-white/30 hover:text-rose-300">×</button></div>)}{!rows.length && <div className="flex items-center justify-between py-3"><p className="text-xs text-white/35">{empty}</p><button type="button" onClick={onAdd} className="text-xs text-[#ff9dcd]">Add</button></div>}</div>; }
function Selector({ label, options, values, onChange, onCreate }: { label: string; options: string[]; values: string[]; onChange: (values: string[]) => void; onCreate?: (value: string) => void }) { const [choice, setChoice] = useState(""); return <label className="block text-[.65rem] text-white/45">{label}<div className="mt-1 flex gap-1"><select value={choice} onChange={event => { const value = event.target.value; setChoice(""); if (value && !values.includes(value)) onChange([...values, value]); }} className={`${field} py-2`}><option value="">Select saved…</option>{options.filter(value => !values.includes(value)).map(value => <option key={value}>{value}</option>)}</select><button type="button" onClick={() => { const value = window.prompt(`Add ${label.toLowerCase()}`); if (value?.trim() && !values.includes(value.trim())) { const name = value.trim(); onCreate?.(name); onChange([...values, name]); } }} className="rounded-lg border border-white/10 px-2 text-white/60">＋</button></div><div className="mt-1 flex flex-wrap gap-1">{values.map(value => <button key={value} type="button" onClick={() => onChange(values.filter(item => item !== value))} className="rounded-full bg-white/[.06] px-2 py-1 text-[.62rem] text-white/70">{value} ×</button>)}</div></label>; }
function ItemEditor({ modal, onClose, onSave, onUpload }: { modal: { type: string; index: number | null; value: Row }; onClose: () => void; onSave: (value: Row) => void; onUpload: (file: File) => void }) { const [value, setValue] = useState<Row>(modal.value); useEffect(() => setValue(modal.value), [modal.value]); const titles: Record<string, string> = { actors: "Person", locations: "Location", outfits: "Outfit", props: "Prop", task: "Task" }; const status: Record<string, string[]> = { actors: ["Considering", "Contacted", "Confirmed", "Completed", "Planned", "Invited"], locations: ["Idea", "Contacted", "Confirmed", "Completed", "Scouting", "Permission requested", "Secured"], outfits: ["Needed", "Sourcing", "Ready", "Sourced"], props: ["Needed", "Sourcing", "Ready", "Sourced"], task: ["To Do", "In Progress", "Done"] }; const fields: Record<string, Array<[string, string]>> = { actors: [["name", "Name"], ["role", "Role"], ["email", "Email"], ["phone", "Phone"], ["agreement", "Agreement or notes"]], locations: [["name", "Location name"], ["address", "Address"], ["notes", "Notes"]], outfits: [["name", "Outfit"], ["notes", "Notes"]], props: [["name", "Prop"], ["notes", "Notes"]], task: [["name", "Task"], ["dueDate", "Due date"]] }; return <div className="fixed inset-0 z-[170] grid place-items-center bg-black/75 p-3" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><form onSubmit={event => { event.preventDefault(); onSave(value); }} className="max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-2xl border border-white/10 bg-[#15151b] p-5 shadow-2xl sm:p-6"><div className="flex items-center"><h2 className="mr-auto text-base font-bold">{modal.index === null ? `Add ${titles[modal.type]}` : `Edit ${titles[modal.type]}`}</h2><button type="button" onClick={onClose} className="px-2 text-white/45">×</button></div><div className="mt-3 space-y-3">{fields[modal.type].map(([key, title]) => <label key={key} className="block text-[.68rem] text-white/45">{title}<input type={key === "dueDate" ? "date" : "text"} list={key === "role" ? "music-video-roles" : undefined} value={value[key] || ""} onChange={event => setValue({ ...value, [key]: event.target.value })} className={`${field} mt-1`}/></label>)}{modal.type !== "task" && <label className="block text-[.68rem] text-white/45">Status<select value={value.status || status[modal.type][0]} onChange={event => setValue({ ...value, status: event.target.value })} className={`${field} mt-1`}>{status[modal.type].map(option => <option key={option}>{option}</option>)}</select></label>}{["outfits", "props", "locations"].includes(modal.type) && <><label className="block text-[.68rem] text-white/45">Image URL<input value={value.imageUrl || value.reference || ""} onChange={event => setValue({ ...value, imageUrl: event.target.value })} placeholder="https://…" className={`${field} mt-1`}/></label><label className="block text-[.68rem] text-white/45">Or upload an image<input type="file" accept="image/*" onChange={event => { const file = event.target.files?.[0]; if (file) onUpload(file); }} className="mt-1 block w-full text-xs text-white/60"/></label>{(value.imageUrl || value.reference) && <img src={value.imageUrl || value.reference} alt="Item preview" className="h-24 w-24 rounded-lg object-cover"/>}</>}</div><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-lg border border-white/10 px-3 py-2 text-xs">Cancel</button><button className="rounded-lg bg-[#FD52AF] px-4 py-2 text-xs font-bold text-black">Save</button></div></form></div>; }
